import{_ as t,o as s,c as o,ah as d}from"./chunks/framework.rk_qxSDs.js";const g=JSON.parse('{"title":"CORS Configuration","description":"All options of the cors plugin and how wildcards behave with credentials.","frontmatter":{"title":"CORS Configuration","description":"All options of the cors plugin and how wildcards behave with credentials.","relatedPlugins":["body","cookie"]},"headers":[],"relativePath":"cors/configuration.md","filePath":"cors/configuration.md","lastUpdated":1795602954000}'),a={name:"cors/configuration.md"};function i(n,e,r,c,h,l){return s(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p><code>cors(options?)</code> takes one object; every option is optional. The options are the <code>Options</code> type; <a href="/cors/helpers#resolveoptions"><code>resolveOptions()</code></a> turns them into <code>ResolvedOptions</code> with the defaults below.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>origin</code></td><td><code>boolean | string | RegExp | (string | RegExp)[] | (origin: string) =&gt; boolean</code></td><td><code>&#39;*&#39;</code></td><td>Which origins get <code>Access-Control-Allow-Origin</code>, and with which value; <code>false</code> turns the plugin off</td></tr><tr><td><code>methods</code></td><td><code>&#39;*&#39; | string[]</code></td><td><code>&#39;*&#39;</code></td><td><code>Access-Control-Allow-Methods</code> on a preflight, joined with <code>,</code></td></tr><tr><td><code>allowHeaders</code></td><td><code>&#39;*&#39; | string[]</code></td><td><code>&#39;*&#39;</code></td><td><code>Access-Control-Allow-Headers</code> on a preflight; <code>&#39;*&#39;</code> mirrors the request&#39;s <code>Access-Control-Request-Headers</code></td></tr><tr><td><code>exposeHeaders</code></td><td><code>&#39;*&#39; | string[]</code></td><td><code>&#39;*&#39;</code></td><td><code>Access-Control-Expose-Headers</code> on the other responses, joined with <code>,</code></td></tr><tr><td><code>credentials</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Sends <code>Access-Control-Allow-Credentials: true</code> on every response</td></tr><tr><td><code>maxAge</code></td><td><code>string | number | false</code></td><td><code>false</code></td><td><code>Access-Control-Max-Age</code> on a preflight, in seconds; <code>false</code> sends none</td></tr><tr><td><code>preflight</code></td><td><code>{ status?: number; continue?: boolean }</code></td><td><code>{ status: 204, continue: false }</code></td><td>Status of the preflight response, or let your own <code>OPTIONS</code> handler answer</td></tr></tbody></table><p>For <code>methods</code>, <code>allowHeaders</code> and <code>exposeHeaders</code>, <code>[&#39;*&#39;]</code> is the same as <code>&#39;*&#39;</code>. An empty array sends no <code>Access-Control-Allow-Methods</code> or <code>Access-Control-Expose-Headers</code>; for <code>allowHeaders</code> it is the same as <code>&#39;*&#39;</code>.</p><h3 id="origin" tabindex="-1"><code>origin</code> <a class="header-anchor" href="#origin" aria-label="Permalink to &quot;`origin`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Value</th><th><code>Access-Control-Allow-Origin</code></th><th><code>Vary: origin</code></th></tr></thead><tbody><tr><td><code>&#39;*&#39;</code> (default)</td><td><code>*</code>, on every response</td><td>no</td></tr><tr><td><code>true</code></td><td>The request&#39;s <code>Origin</code>; none when the request has no <code>Origin</code></td><td>yes</td></tr><tr><td>Any other string, such as <code>&#39;https://app.example.com&#39;</code> or <code>&#39;null&#39;</code></td><td>That string, on every response, whatever the request&#39;s <code>Origin</code></td><td>yes</td></tr><tr><td><code>RegExp</code></td><td>The request&#39;s <code>Origin</code> when the pattern matches it</td><td>yes</td></tr><tr><td>Array of strings and <code>RegExp</code>s</td><td>The request&#39;s <code>Origin</code> when an entry matches it: a string by equality, a <code>RegExp</code> with <code>test()</code></td><td>yes</td></tr><tr><td>Function <code>(origin) =&gt; boolean</code></td><td>The request&#39;s <code>Origin</code> when the function returns <code>true</code>; not called without an <code>Origin</code></td><td>yes</td></tr><tr><td><code>false</code></td><td>None: the plugin passes every request on, preflights too, and sets no header</td><td>no</td></tr></tbody></table><p>A fixed string is not a check: other origins get the same value and the browser rejects the response. To send no header to other origins, use an array of one (<a href="/cors/recipes#allow-one-origin">Allow One Origin</a>).</p><p>When no entry matches, the response has no <code>Access-Control-Allow-Origin</code>, so the browser blocks it; the plugin still sets the other headers and a preflight is still answered. <code>Vary: origin</code> is sent for every option except <code>&#39;*&#39;</code> and <code>false</code>, matching or not, so a shared cache does not serve the answer to one origin to another. A <code>RegExp</code> with the <code>g</code> or <code>y</code> flag is copied without those flags before each test, so its <code>lastIndex</code> does not make the result alternate between requests.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { App, defineCoreHandler } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;routup&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { cors } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@routup/cors&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> App</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cors</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    origin: [</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;https://app.example.com&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        /</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">\\.</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">staging</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">\\.</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">example</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">\\.</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ],</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}));</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">defineCoreHandler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Hello, World!&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span></code></pre></div><p><a href="/cors/recipes#an-allow-list">An Allow-List</a> shows a function.</p><h3 id="methods" tabindex="-1"><code>methods</code> <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;`methods`&quot;">​</a></h3><p>The methods a preflight allows, as a list or <code>&#39;*&#39;</code>. A literal <code>*</code> is only a wildcard for requests without credentials, so with <a href="#credentials"><code>credentials</code></a> a <code>&#39;*&#39;</code> is sent as <code>GET,HEAD,POST,PUT,PATCH,DELETE,OPTIONS</code>.</p><h3 id="allowheaders" tabindex="-1"><code>allowHeaders</code> <a class="header-anchor" href="#allowheaders" aria-label="Permalink to &quot;`allowHeaders`&quot;">​</a></h3><p>The request headers a preflight allows. With <code>&#39;*&#39;</code>, an empty array or <code>[&#39;*&#39;]</code>, the preflight answers with the request&#39;s own <code>Access-Control-Request-Headers</code>, so a literal <code>*</code> is never sent and this is safe with credentials; a preflight without that header gets no <code>Access-Control-Allow-Headers</code>. Whenever the header is sent, <code>Vary: access-control-request-headers</code> is appended.</p><h3 id="exposeheaders" tabindex="-1"><code>exposeHeaders</code> <a class="header-anchor" href="#exposeheaders" aria-label="Permalink to &quot;`exposeHeaders`&quot;">​</a></h3><p>The response headers a script may read beyond the CORS-safelisted ones. A browser treats <code>*</code> as a wildcard only for requests without credentials; with <a href="#credentials"><code>credentials</code></a>, list the headers you need, such as <code>[&#39;x-request-id&#39;]</code>.</p><h3 id="credentials" tabindex="-1"><code>credentials</code> <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;`credentials`&quot;">​</a></h3><p><code>true</code> sends <code>Access-Control-Allow-Credentials: true</code>, on a preflight and on the other responses, so the browser sends cookies and reads the response. Browsers do not accept a literal <code>*</code> on a request with credentials, so the plugin handles each wildcard:</p><table tabindex="0"><thead><tr><th>Option with <code>&#39;*&#39;</code></th><th>With <code>credentials: true</code></th></tr></thead><tbody><tr><td><code>methods</code></td><td>Expanded to <code>GET,HEAD,POST,PUT,PATCH,DELETE,OPTIONS</code></td></tr><tr><td><code>allowHeaders</code></td><td>Mirrors <code>Access-Control-Request-Headers</code>, as without credentials</td></tr><tr><td><code>exposeHeaders</code></td><td>Sent as <code>*</code>; the response is not blocked, but scripts read only the CORS-safelisted headers. The plugin logs a warning</td></tr><tr><td><code>origin</code></td><td>Sent as <code>*</code>, so the browser blocks the response. The plugin logs a warning and does not switch to reflecting the origin, which would let any site send requests with the user&#39;s cookies. Use <code>true</code> or an allow-list</td></tr></tbody></table><p>The warnings are written with <code>console.warn</code> when the plugin is installed with <code>app.use()</code>, or when <a href="/cors/helpers#createhandler"><code>createHandler()</code></a> is called; not per request. <a href="/cors/recipes#credentials">Credentials</a> is a complete setup.</p><h3 id="maxage" tabindex="-1"><code>maxAge</code> <a class="header-anchor" href="#maxage" aria-label="Permalink to &quot;`maxAge`&quot;">​</a></h3><p>How long, in seconds, the browser may reuse a preflight answer. A number is sent as its string; <code>false</code> (the default) sends no <code>Access-Control-Max-Age</code>, and the browser applies its own default. See <a href="/cors/recipes#preflight-caching">Preflight Caching</a>.</p><h3 id="preflight" tabindex="-1"><code>preflight</code> <a class="header-anchor" href="#preflight" aria-label="Permalink to &quot;`preflight`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>status</code></td><td><code>number</code></td><td><code>204</code></td><td>Status of the preflight response, for clients that do not accept <code>204</code></td></tr><tr><td><code>continue</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Set the preflight headers, then call <code>event.next()</code> instead of answering</td></tr></tbody></table><p>With <code>continue</code>, your <code>OPTIONS</code> route answers the preflight and the headers are already on <code>event.response</code> (<a href="/cors/recipes#your-own-preflight-handler">Your Own Preflight Handler</a>). Without such a route, routup answers the <code>OPTIONS</code> request itself, with status <code>200</code> and an <code>Allow</code> header.</p>',26)])])}const k=t(a,[["render",i]]);export{g as __pageData,k as default};
